    return `<button type="button" class="campus-schedule-card event-${ctx.esc(entry.type)}" data-academy="calendarEntry" data-id="${ctx.esc(entry.id)}"><span class="schedule-time">${time}</span><span class="schedule-card-body"><span class="schedule-card-tags">${ctx.badge(entry.source==='class'?({lecture:'Lecture',tutorial:'Tutorial',lab:'Lab',seminar:'Seminar','office-hours':'Office hours'}[entry.classType]||'Class'):labels[entry.type]||'Event')}${entry.minutes?ctx.badge(entry.minutes+' min'):''}${continued?ctx.badge('Continued from previous day'):continues?ctx.badge('Continues tomorrow'):''}</span><strong class="schedule-card-title">${ctx.esc(title)}</strong>${entry.courseTitle?`<span class="schedule-course">${ctx.esc(entry.courseTitle)}</span>`:''}${entry.location?`<span class="schedule-location">${ctx.icon('building')}${ctx.esc(entry.location)}</span>`:''}${entry.source==='assignment'?`<span class="schedule-description">${ctx.esc(entry.maxPoints)} points · Open assignment details</span>`:''}</span><span class="schedule-card-arrow" aria-hidden="true">${ctx.icon('chevron')}</span></button>`;
