    return `<div class="academic-overview-layout"><section class="panel academic-course-panel"><div class="panel-head"><div><p class="eyebrow">${learner?'YOUR ENROLLMENTS':'YOUR TEACHING'}</p><h2>${learner?'Course performance snapshot':'Course allocations'}</h2></div>${actionButton(ctx,learner?'View grade sheet':'Teaching history','academicView',learner?'grades':'history','ghost')}</div>${learner?'<p class="form-help">Assignment percentages use released points only. Each course keeps its own assessment scale.</p>':''}${records.map(r=>academicCourseRow(ctx,r,learner)).join('')}</section><aside class="stack">${learner?`<section class="panel academic-next"><p class="eyebrow">YOUR NEXT STEPS</p><h2>Keep your semester moving.</h2><div class="academic-next-counts"><span><strong>${unsubmitted.length}</strong> assignments to submit</span><span><strong>${totals.quizzes-totals.attempts}</strong> quizzes to complete</span></div>${unsubmitted.slice(0,2).map(a=>`<div class="academic-next-item"><strong>${ctx.esc(a.title)}</strong><small>${ctx.esc(a.course.code||a.course.title)} · Due ${dateLabel(a.dueDate)}${a.dueDate<ctx.store.today()?' · Past due':''}</small>${actionButton(ctx,'Open assignment','submitAssignment',a.id,'ghost')}</div>`).join('')}${!unsubmitted.length?'<p class="muted">All selected assignments have been submitted.</p>':''}${totals.awaiting?`<p class="form-help">${totals.awaiting} submitted ${totals.awaiting===1?'assignment is':'assignments are'} awaiting released feedback.</p>`:''}</section><section class="panel academic-feedback"><p class="eyebrow">PUBLISHED FEEDBACK</p><h2>Learn from your latest work.</h2>${feedback.map(a=>`<div class="academic-feedback-item"><div><strong>${ctx.esc(a.course.code||a.course.title)}</strong>${ctx.badge(a.submission.score+'/'+a.maxPoints,'green')}</div><p>${ctx.esc(a.title)}</p><p class="muted">${ctx.esc(a.submission.feedback||'Your educator has released this assessment score.')}</p>${actionButton(ctx,'View submission','submitAssignment',a.id,'ghost')}</div>`).join('')||'<p class="muted">Your educator’s feedback appears here after grades are released.</p>'}</section>`:`<section class="panel"><p class="eyebrow">YOUR ACADEMIC HOME</p><h2>${ctx.esc(scope.data.departments.find(d=>d.id===scope.profile.departmentId)?.title||'Academic department')}</h2><p class="muted">Teaching allocations appear for the selected academic terms. Review learner submissions from each course.</p>${actionButton(ctx,'Browse course allocations','collegePage',scope.institution?.role==='educator'?'My teaching':'Courses','secondary')}</section>`}</aside></div>`;
