    const visible=all.filter(n=>(status==='archived'?archivedNotice(n,today):!archivedNotice(n,today)&&(status!=='unread'||!n.isRead))&&(category==='all'||n.category===category)&&[n.title,n.body,n.office,n.reference].join(' ').toLowerCase().includes(query)).sort(noticeOrder);
