    return `<section class="panel"><h2>Assessment completion records</h2><p class="form-help">These local records require at least one assessment and at least 60% on every current released assignment and quiz revision. Lesson progress and attendance do not count toward this eligibility. External accreditation and public verification are not provided.</p>${eligibility.map(e=>`<article class="assessment-row"><div><strong>${ctx.esc(scope.data.roster.find(u=>u.id===e.userId)?.displayName||ctx.store.getUser().displayName)} · ${ctx.esc(scope.courses.find(c=>c.id===e.courseId)?.title)}</strong><p>${e.eligible?'Assessment requirements met.':(e.blockers||[]).map(b=>ctx.esc(b.title+': '+b.reason)).join('<br>')}</p></div>${scope.courses.find(c=>c.id===e.courseId)?.canTeach&&!e.activeRecordId&&e.eligible?actionButton(ctx,'Issue record','issueCertificate',e.courseId):e.activeRecordId?ctx.badge('Record already issued','green'):''}</article>`).join('')}${records.map(r=>`<article class="assessment-row"><div><strong>${ctx.esc(r.courseTitle)} · ${ctx.esc(r.learnerName)}</strong><p>${ctx.esc(r.serial)} · Issued ${dateLabel(r.issuedAt)}</p>${ctx.badge(r.revokedAt?'Revoked':'Issued',r.revokedAt?'amber':'green')}${r.revokedAt?`<p>${ctx.esc(r.revocationReason)}</p>`:''}</div><div class="actions">${actionButton(ctx,'View / print','viewCertificate',r.id)}${!r.revokedAt&&scope.courses.find(c=>c.id===r.courseId)?.canTeach?actionButton(ctx,'Revoke','revokeCertificate',r.id,'danger'):''}</div></article>`).join('')||noRecords(ctx,'No records issued yet','Requirements and issued records are shown here.')}</section>`;
