        return intro(page==='Students'?'Your college’s students.':'Your college’s faculty.','Academic identity and course allocations are maintained independently.',ab('Enroll account','enroll','','primary'))+`<section class="panel">${people.length?table(ctx,['Name','Academic ID','Program / department','Courses','Academic record'],people.map(p=>`<tr><td><strong>${esc(p.displayName)}</strong><br><small>@${esc(p.username)}</small></td><td>${esc(p.rollNumber||'Not recorded')}</td><td>${esc(data.programs.find(d=>d.id===p.programId)?.title||data.departments.find(d=>d.id===p.departmentId)?.title||'Not assigned')}</td><td>${courses.filter(c=>c.learnerIds.includes(p.userId)||c.teacherIds.includes(p.userId)).map(c=>esc(c.code||c.title)).join(', ')||'No allocations'}</td><td>${ab('Edit profile','updateAcademicProfile',p.userId)}</td></tr>`)):noRecords(ctx,'No members in this role','Enroll an existing account in a course to add a college member.')}</section>`;
